const raw = $input.first()?.json || {};
const q = raw.callback_query || raw;
const queryId = String(q.id || '');
const msg = q.message || {};
const data = String(q.data || '');
const parts = data.split('|');
const cmd = parts[0] || '';
const productKey = parts[1] || '';

let newStatus = 'approved';
let label = '✅ Produkt freigegeben (status = approved) — wird automatisch produziert!';
if (cmd === 'tts_pause') {
  newStatus = 'paused';
  label = '⏸️ Produkt pausiert (status = paused) — wird übersprungen.';
} else if (cmd === 'tts_winner') {
  newStatus = 'winner';
  label = '🏆 Produkt als WINNER markiert (status = winner) — Dauer-Skalierung aktiv!';
}

return [{
  json: {
    query_id: queryId,
    product_key: productKey,
    new_status: newStatus,
    answer_text: label,
    chat_id: msg.chat?.id || $env.TELEGRAM_CHAT_ID
  }
}];

const candidates = $('Evaluate Account & Sunday Apify 5-Candidate Radar').all().map(i => i.json || {});
const scrapedItems = $input.all().map(i => i.json || {}).filter(x => x.product_id && x.country === 'DE');

const byId = new Map();
for (const s of scrapedItems) {
  byId.set(String(s.product_id), s);
}

const out = [];
for (const c of candidates) {
  // Match exact DE product_id from live Apify DE TikTok Shop scrape, or best match for search_keyword
  let live = byId.get(String(c.de_product_id || ''));
  if (!live) {
    const kw = String(c.search_keyword || '').toLowerCase();
    live = scrapedItems.find(s => String(s.search_query || '').toLowerCase() === kw);
  }

  const deId = (live && live.product_id) ? String(live.product_id) : String(c.de_product_id || '');
  const title = (live && live.title) ? String(live.title) : c.product_name;
  const link = (live && live.url) ? String(live.url) : ('https://shop.tiktok.com/de/pdp/' + deId);
  const appDeepLink = 'https://www.tiktok.com/view/product/' + deId;
  const packshot = (live && live.image_url) ? String(live.image_url) : c.packshot_image_url;
  const priceEur = (live && live.price) ? Number(live.price) : Number(c.price_eur);
  const soldCount = (live && live.sold_count !== undefined) ? Number(live.sold_count) : Number(c.sales_30d_est);
  const sellerName = (live && live.seller && live.seller.name) ? String(live.seller.name) : 'TikTok Shop DE Händler';

  const tg = [
    '🇩🇪 <b>Deutsches TikTok-Shop Produkt (' + String(c.status || 'candidate').toUpperCase() + ')</b>',
    '<b>Original-Titel (DE Shop):</b> ' + title,
    '<b>DE Produkt-ID:</b> <code>' + deId + '</code> (' + sellerName + ')',
    '<b>Preis & Verkäufe (DE):</b> ' + priceEur + ' EUR | ' + soldCount + ' verkauft | ~' + c.commission_pct + '% Provision',
    '<b>Problem gelöst:</b> ' + c.problem_solved,
    '<b>DE Shop-Link (PDP):</b> <a href="' + link + '">shop.tiktok.com/de/pdp/' + deId + '</a>',
    '<b>In-App Produkt-Link:</b> <a href="' + appDeepLink + '">tiktok.com/view/product/' + deId + '</a>',
    '<b>Original-Produktbild (TikTok CDN EU):</b> <a href="' + packshot + '">Original-Packshot öffnen</a>',
    '',
    '<i>Tippe unten auf einen Button, um den Status in tts_products sofort zu steuern:</i>'
  ].join('\n');

  out.push({
    json: {
      ...c,
      product_name: title,
      tiktok_shop_url: link,
      packshot_image_url: packshot,
      price_eur: priceEur,
      sales_30d_est: soldCount,
      tg_text: tg
    }
  });
}
return out;
